    shop_id, promotion_enabled, balance_reminder_enabled, strategy_config_json, strategy_configured, create_time, update_time
) VALUES (
    #{shopId}, 0, 1, #{strategyConfigJson}, #{strategyConfigured}, #{now}, #{now}
)
ON DUPLICATE KEY UPDATE update_time = update_time

INSERT INTO mt_promotion_setting (
    shop_id, promotion_enabled, balance_reminder_enabled, strategy_config_json, strategy_configured, create_time, update_time
) VALUES (
    #{shopId}, #{promotionEnabled}, #{balanceReminderEnabled}, #{strategyConfigJson}, #{strategyConfigured}, #{createTime}, #{updateTime}
