mapper.select:
SELECT s.id AS setting_id, s.shop_id, COALESCE(sh.poi_name, sh.name) AS shop_name, sh.poi_id, sh.shipping_time, s.strategy_config_json, t.access_token, t.expires_at AS token_expires_at FROM mt_promotion_setting s INNER JOIN mt_shop sh ON sh.id = s.shop_id INNER JOIN mt_access_token t ON t.shop_id = s.shop_id WHERE s.promotion_enabled = 1 AND s.strategy_configured = 1 AND s.strategy_config_json IS NOT NULL AND s.strategy_config_json != '' AND t.access_token IS NOT NULL AND t.access_token != '' AND t.auth_status = 1 AND (t.expires_at IS NULL OR t.expires_at > #{now})
AND s.shop_id > #{lastShopId}
AND EXISTS ( SELECT 1 FROM mt_shop_right r WHERE r.shop_id = s.shop_id AND r.service_code IN ('H5_PROMOTION', 'VIP_CODE') AND ( (r.type = 2 AND r.expire_at IS NOT NULL AND r.expire_at > #{now}) OR (r.type != 2 AND r.remaining_times IS NOT NULL AND r.remaining_times > 0) ) ) ORDER BY s.shop_id ASC LIMIT #{limit}

SELECT s.id AS setting_id, s.shop_id, COALESCE(sh.poi_name, sh.name) AS shop_name, sh.poi_id, t.access_token, t.expires_at AS token_expires_at, t.id AS access_token_id, t.op_biz_code, t.order_push_blocked FROM mt_promotion_setting s INNER JOIN mt_shop sh ON sh.id = s.shop_id INNER JOIN mt_access_token t ON t.shop_id = s.shop_id WHERE s.promotion_enabled = 1 AND t.access_token IS NOT NULL AND t.access_token != '' AND t.auth_status = 1 AND t.op_biz_code IS NOT NULL AND t.op_biz_code != '' AND sh.poi_id IS NOT NULL AND sh.poi_id != '' AND (t.expires_at IS NULL OR t.expires_at > #{now})
AND s.shop_id > #{lastShopId}
AND NOT EXISTS ( SELECT 1 FROM mt_shop_right r WHERE r.shop_id = s.shop_id AND r.service_code IN ('H5_PROMOTION', 'VIP_CODE') AND ( (r.type = 2 AND r.expire_at IS NOT NULL AND r.expire_at > #{now}) OR (r.type != 2 AND r.remaining_times IS NOT NULL AND r.remaining_times > 0) ) ) ORDER BY s.shop_id ASC LIMIT #{limit}
